import assert from "node:assert/strict";
import { spawn, spawnSync } from "node:child_process";
import {
  copyFileSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import process from "node:process";
import { test } from "node:test";
import {
  nextVersion,
  prepareContents,
  prepareRelease,
} from "./prepare-release.mjs";

const files = {
  "package.json":
    '{\n  "name": "nomadic",\n  "version": "1.2.3",\n  "other": true\n}\n',
  "src-tauri/tauri.conf.json": '{\n  "version": "1.2.3",\n  "other": true\n}\n',
  "src-tauri/Cargo.toml":
    '[package]\nname = "nomadic"\nversion = "1.2.3"\nedition = "2021"\n',
  "src-tauri/Cargo.lock":
    '# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\nversion = 4\n\n[[package]]\nname = "nomadic"\nversion = "1.2.3"\n',
};

function fixture(t) {
  const root = mkdtempSync(join(tmpdir(), "nomadic-prepare-"));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  for (const [path, content] of Object.entries(files)) {
    mkdirSync(dirname(join(root, path)), { recursive: true });
    writeFileSync(join(root, path), content);
  }
  mkdirSync(join(root, "src-tauri/src"));
  writeFileSync(join(root, "src-tauri/src/lib.rs"), "");
  return root;
}

function runCli(root, replies) {
  return new Promise((resolveResult, reject) => {
    const child = spawn(
      process.execPath,
      [join(root, ".github/scripts/prepare-release.mjs")],
      {
        cwd: root,
        stdio: "pipe",
      },
    );
    let output = "";
    let errors = "";
    let index = 0;
    child.stdout.on("data", (data) => {
      output += data;
      if (
        output.includes(index === 0 ? "Choose patch" : "Enter a stable") &&
        index < replies.length
      ) {
        child.stdin.write(`${replies[index++]}\n`);
      }
    });
    child.stderr.on("data", (data) => {
      errors += data;
    });
    child.on("error", reject);
    child.on("close", (status) => resolveResult({ status, output, errors }));
  });
}

function installCli(root) {
  const directory = join(root, ".github/scripts");
  mkdirSync(directory, { recursive: true });
  for (const script of ["prepare-release.mjs", "ci.mjs"]) {
    copyFileSync(resolve(".github/scripts", script), join(directory, script));
  }
}

test("increments stable versions and accepts only increasing manual versions", () => {
  assert.equal(nextVersion("1.2.3", "patch"), "1.2.4");
  assert.equal(nextVersion("1.2.3", "minor"), "1.3.0");
  assert.equal(nextVersion("1.2.3", "major"), "2.0.0");
  assert.equal(nextVersion("1.2.3", "4.5.6"), "4.5.6");
  assert.equal(
    nextVersion("99999999999999999999.0.0", "major"),
    "100000000000000000000.0.0",
  );
  for (const invalid of [
    "1.2.3",
    "1.1.9",
    "1.02.4",
    "v2.0.0",
    "2.0.0-rc.1",
    "invalid",
  ]) {
    assert.throws(() => nextVersion("1.2.3", invalid));
  }
});

test("validates application versions without editing the Cargo lockfile", () => {
  const result = prepareContents(files, "patch");
  assert.equal(result.next, "1.2.4");
  assert.equal(result.updated["src-tauri/Cargo.lock"], undefined);
  for (const path of Object.keys(files).filter(
    (path) => !path.endsWith("Cargo.lock"),
  )) {
    assert.throws(() =>
      prepareContents(
        { ...files, [path]: files[path].replace("1.2.3", "1.2.5") },
        "patch",
      ),
    );
  }
  const nested = prepareContents(
    {
      ...files,
      "package.json": files["package.json"].replace(
        '"other": true',
        '"other": {\n    "version": "1.2.3"\n  }',
      ),
    },
    "patch",
  );
  assert.match(nested.updated["package.json"], /"version": "1\.2\.4"/);
  assert.match(nested.updated["package.json"], /"version": "1\.2\.3"/);
  assert.throws(
    () =>
      prepareContents(
        {
          ...files,
          "package.json": files["package.json"].replace(
            '"other": true',
            '"version": "1.2.3",\n  "other": true',
          ),
        },
        "patch",
      ),
    /exactly one/,
  );
});

test("restores all files if Cargo fails after changing the lockfile", (t) => {
  const root = fixture(t);
  assert.throws(
    () =>
      prepareRelease(root, "patch", {
        readFileSync,
        writeFileSync,
        execFileSync(command, args) {
          assert.equal(command, "cargo");
          assert.deepEqual(args.slice(0, 2), ["update", "--workspace"]);
          writeFileSync(join(root, "src-tauri/Cargo.lock"), "partial");
          throw new Error("simulated Cargo failure");
        },
      }),
    /simulated Cargo failure/,
  );
  for (const [path, content] of Object.entries(files)) {
    assert.equal(readFileSync(join(root, path), "utf8"), content);
  }
});

test("restores original contents after a partial write failure", (t) => {
  const root = fixture(t);
  let failed = false;
  assert.throws(
    () =>
      prepareRelease(root, "patch", {
        readFileSync,
        writeFileSync(path, content) {
          if (!failed && path.endsWith("Cargo.toml")) {
            failed = true;
            writeFileSync(path, "partial");
            throw new Error("simulated write failure");
          }
          writeFileSync(path, content);
        },
      }),
    /simulated write failure/,
  );
  for (const [path, content] of Object.entries(files)) {
    assert.equal(readFileSync(join(root, path), "utf8"), content);
  }
});

test("interactive choices update all versions", async (t) => {
  for (const [replies, expected] of [
    [["patch"], "1.2.4"],
    [["minor"], "1.3.0"],
    [["major"], "2.0.0"],
    [["manual", "2.4.0"], "2.4.0"],
  ]) {
    const root = fixture(t);
    installCli(root);
    const result = await runCli(root, replies);
    assert.equal(result.status, 0, result.errors);
    assert.ok(result.output.includes(`Prepared 1.2.3 -> ${expected}`));
    for (const path of Object.keys(files)) {
      assert.ok(
        readFileSync(join(root, path), "utf8").includes(`"${expected}"`),
      );
    }
    const cargo = spawnSync(
      "cargo",
      [
        "metadata",
        "--locked",
        "--offline",
        "--format-version",
        "1",
        "--manifest-path",
        join(root, "src-tauri/Cargo.toml"),
      ],
      { encoding: "utf8" },
    );
    assert.equal(cargo.status, 0, cargo.stderr);
  }
});

test("cancellation and invalid input leave all files untouched", async (t) => {
  for (const replies of [
    [""],
    ["manual", ""],
    ["manual", "1.2.3-rc.1"],
    ["wrong"],
  ]) {
    const root = fixture(t);
    installCli(root);
    const result = await runCli(root, replies);
    assert.equal(result.status, replies.includes("") ? 0 : 1);
    for (const [path, content] of Object.entries(files)) {
      assert.equal(readFileSync(join(root, path), "utf8"), content);
    }
  }
});
